-- +goose Up
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL DEFAULT 1, archived INTEGER NOT NULL DEFAULT 0, current_version_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE agent_versions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, version INTEGER NOT NULL, schema_version INTEGER NOT NULL, config_json TEXT NOT NULL, config_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(agent_id,version));
CREATE TABLE mcp_servers (id TEXT PRIMARY KEY, name TEXT NOT NULL, endpoint TEXT NOT NULL, transport TEXT NOT NULL, auth_env TEXT NOT NULL DEFAULT '', enabled INTEGER NOT NULL, validation_state TEXT NOT NULL, latest_discovery_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE mcp_discoveries (id TEXT PRIMARY KEY, server_id TEXT NOT NULL, discovery_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE mcp_tools (discovery_id TEXT NOT NULL REFERENCES mcp_discoveries(id) ON DELETE RESTRICT, remote_name TEXT NOT NULL, schema_json TEXT NOT NULL, schema_hash TEXT NOT NULL, PRIMARY KEY(discovery_id,remote_name));
CREATE TABLE agent_mcp_tools (agent_version_id TEXT NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT, mcp_server_id TEXT NOT NULL, remote_name TEXT NOT NULL, schema_hash TEXT NOT NULL, required INTEGER NOT NULL, PRIMARY KEY(agent_version_id,mcp_server_id,remote_name));
CREATE TABLE sessions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT, config_hash TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL, provider_stack_json TEXT NOT NULL, turn_count INTEGER NOT NULL, safe_summary TEXT NOT NULL);
CREATE TABLE turns (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT, ordinal INTEGER NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, transcript TEXT, assistant_text TEXT, latencies_json TEXT NOT NULL, interrupted INTEGER NOT NULL, tools_json TEXT NOT NULL, UNIQUE(session_id,ordinal));
CREATE TABLE trace_spans (id TEXT PRIMARY KEY, session_id TEXT REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, parent_id TEXT REFERENCES trace_spans(id) ON DELETE RESTRICT, name TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, attributes_json TEXT NOT NULL);
CREATE TABLE trace_events (id TEXT PRIMARY KEY, span_id TEXT REFERENCES trace_spans(id) ON DELETE RESTRICT, session_id TEXT REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, name TEXT NOT NULL, occurred_at TEXT NOT NULL, attributes_json TEXT NOT NULL);
CREATE TABLE tool_calls (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, mcp_server_id TEXT, remote_name TEXT NOT NULL, schema_hash TEXT NOT NULL, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL, arguments_summary TEXT NOT NULL, result_summary TEXT NOT NULL);
CREATE TABLE eval_cases (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, name TEXT NOT NULL, caller_json TEXT NOT NULL, expect_json TEXT NOT NULL, expected_answer TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(agent_id,name));
CREATE TABLE eval_suites (agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE RESTRICT, runs INTEGER NOT NULL CHECK(runs BETWEEN 1 AND 5), min_pass INTEGER NOT NULL CHECK(min_pass >= 1 AND min_pass <= runs), pass_threshold REAL NOT NULL CHECK(pass_threshold BETWEEN 0 AND 1), judge_provider TEXT, judge_model TEXT, updated_at TEXT NOT NULL);
CREATE TABLE eval_scorer_settings (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, scorer TEXT NOT NULL, threshold REAL, judge_provider TEXT, judge_model TEXT, live_enabled INTEGER NOT NULL DEFAULT 0, sample_rate REAL NOT NULL DEFAULT 0 CHECK(sample_rate BETWEEN 0 AND 1), kind TEXT NOT NULL DEFAULT 'builtin' CHECK(kind IN ('builtin','custom')), definition_json TEXT, updated_at TEXT NOT NULL, PRIMARY KEY(agent_id,scorer));
CREATE TABLE eval_runs (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT REFERENCES agent_versions(id) ON DELETE RESTRICT, config_hash TEXT NOT NULL, draft INTEGER NOT NULL, draft_config_json TEXT, draft_tools_json TEXT, source TEXT NOT NULL CHECK(source IN ('suite')), scope TEXT NOT NULL CHECK(scope IN ('suite','case')), case_id TEXT, providers TEXT NOT NULL CHECK(providers IN ('keep','offline','echo')), runs INTEGER NOT NULL, min_pass INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','done')), triggered_by TEXT NOT NULL CHECK(triggered_by IN ('console','api')), passed_cases INTEGER, total_cases INTEGER, created_at TEXT NOT NULL, started_at TEXT, ended_at TEXT, CHECK((draft=1 AND agent_version_id IS NULL) OR (NOT draft=1 AND agent_version_id IS NOT NULL)));
CREATE TABLE eval_results (id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL CHECK(subject_kind IN ('case_run','call')), subject_id TEXT NOT NULL, scorer TEXT NOT NULL, scorer_version INTEGER NOT NULL, version_key TEXT NOT NULL, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT, config_hash TEXT NOT NULL, run_id TEXT REFERENCES eval_runs(id) ON DELETE RESTRICT, case_id TEXT, case_hash TEXT, session_id TEXT NOT NULL, score REAL NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('pass','fail','skipped','error')), reason TEXT NOT NULL, judge_model TEXT, created_at TEXT NOT NULL, UNIQUE(subject_id,scorer,version_key));
CREATE TABLE eval_jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('run_suite','run_case','score_call')), agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT, run_id TEXT REFERENCES eval_runs(id) ON DELETE RESTRICT, subject TEXT NOT NULL, scorer TEXT, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('pending','running','done','failed','dead')), attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL CHECK(max_attempts >= 1), run_after TEXT NOT NULL, lease_owner TEXT, lease_expires_at TEXT, payload TEXT NOT NULL, last_error_category TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TRIGGER agent_versions_immutable_update BEFORE UPDATE ON agent_versions BEGIN SELECT RAISE(ABORT, 'agent version is immutable'); END;
CREATE TRIGGER mcp_discoveries_immutable_update BEFORE UPDATE ON mcp_discoveries BEGIN SELECT RAISE(ABORT, 'MCP discovery is immutable'); END;
CREATE TRIGGER mcp_tools_immutable_update BEFORE UPDATE ON mcp_tools BEGIN SELECT RAISE(ABORT, 'MCP tool is immutable'); END;
CREATE TRIGGER agent_versions_immutable_delete BEFORE DELETE ON agent_versions BEGIN SELECT RAISE(ABORT, 'agent version is immutable'); END;
CREATE TRIGGER mcp_discoveries_immutable_delete BEFORE DELETE ON mcp_discoveries BEGIN SELECT RAISE(ABORT, 'MCP discovery is immutable'); END;
CREATE TRIGGER mcp_tools_immutable_delete BEFORE DELETE ON mcp_tools BEGIN SELECT RAISE(ABORT, 'MCP tool is immutable'); END;
CREATE TRIGGER agent_mcp_tools_immutable_update BEFORE UPDATE ON agent_mcp_tools BEGIN SELECT RAISE(ABORT, 'selected tool is immutable'); END;
CREATE TRIGGER agent_mcp_tools_immutable_delete BEFORE DELETE ON agent_mcp_tools BEGIN SELECT RAISE(ABORT, 'selected tool is immutable'); END;
CREATE TRIGGER agents_current_version_valid BEFORE UPDATE OF current_version_id ON agents WHEN NEW.current_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM agent_versions v WHERE v.id=NEW.current_version_id AND v.agent_id=NEW.id) BEGIN SELECT RAISE(ABORT, 'current version must belong to agent'); END;
CREATE TRIGGER agents_current_version_insert_valid BEFORE INSERT ON agents WHEN NEW.current_version_id IS NOT NULL BEGIN SELECT RAISE(ABORT, 'new agent cannot point at existing version'); END;
CREATE TRIGGER mcp_servers_latest_valid BEFORE UPDATE OF latest_discovery_id ON mcp_servers WHEN NEW.latest_discovery_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mcp_discoveries d WHERE d.id=NEW.latest_discovery_id AND d.server_id=NEW.id) BEGIN SELECT RAISE(ABORT, 'latest discovery must belong to MCP server'); END;
CREATE TRIGGER mcp_servers_latest_insert_valid BEFORE INSERT ON mcp_servers WHEN NEW.latest_discovery_id IS NOT NULL BEGIN SELECT RAISE(ABORT, 'new MCP server cannot point at existing discovery'); END;
CREATE TRIGGER sessions_provenance_valid BEFORE INSERT ON sessions WHEN NOT EXISTS (SELECT 1 FROM agent_versions v WHERE v.id=NEW.agent_version_id AND v.agent_id=NEW.agent_id AND v.config_hash=NEW.config_hash) BEGIN SELECT RAISE(ABORT, 'session provenance mismatch'); END;
CREATE TRIGGER sessions_provenance_immutable BEFORE UPDATE OF agent_id,agent_version_id,config_hash ON sessions BEGIN SELECT RAISE(ABORT, 'session provenance is immutable'); END;
CREATE TRIGGER mcp_servers_referenced_delete BEFORE DELETE ON mcp_servers WHEN EXISTS (SELECT 1 FROM agents a JOIN agent_mcp_tools t ON t.agent_version_id=a.current_version_id WHERE t.mcp_server_id=OLD.id) BEGIN SELECT RAISE(ABORT, 'MCP server referenced by current agent'); END;
